const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const taiwan = ee.Geometry.Polygon(
    [[[119.5, 21.5],
      [119.5, 25.5],
      [122.5, 25.5],
      [122.5, 21.5],
      [119.5, 21.5]]]);

  const date1_start = '2020-02-10';
  const date1_end = '2020-02-25';
  const date2_start = '2020-04-20';
  const date2_end = '2020-05-12';

  const S5P_NO2_COLLECTION = 'COPERNICUS/S5P/NRTI/L3_NO2';
  const NO2_BAND = 'tropospheric_NO2_column_number_density';
  const QUALITY_THRESHOLD = 0.75; // Quality value threshold for Sentinel-5P data
  const REDUCER_SCALE = 3000; // Scale in meters for reduceRegion

  // Function to process NO2 data for a given period
  const processNO2 = (startDate, endDate, geometry) => {
    let collection = ee.ImageCollection(S5P_NO2_COLLECTION)
      .filterDate(startDate, endDate)
      .filterBounds(geometry)
      .select([NO2_BAND, 'quality_value'])
      .filter(ee.Filter.gte('quality_value', QUALITY_THRESHOLD))
      .map(image => image.select(NO2_BAND).copyProperties(image, ['system:time_start'])); // Select only NO2 band

    return collection;
  };

  // 2. Data Acquisition & Check - Period 1
  let collection1 = processNO2(date1_start, date1_end, taiwan);
  let collection1Size = await collection1.size().getInfo();

  if (collection1Size === 0) {
    console.log("No Sentinel-5P images found for Feb 10-25, 2020 over Taiwan.");
    console.log("C1");
    return;
  }
  console.log(`Period 1 Images (Feb 10-25, 2020): ${collection1Size}`);

  // 2. Data Acquisition & Check - Period 2
  let collection2 = processNO2(date2_start, date2_end, taiwan);
  let collection2Size = await collection2.size().getInfo();

  if (collection2Size === 0) {
    console.log("No Sentinel-5P images found for Apr 20-May 12, 2020 over Taiwan.");
    console.log("C1");
    return;
  }
  console.log(`Period 2 Images (Apr 20-May 12, 2020): ${collection2Size}`);

  // Create a composite image (mean) for each period
  let meanImage1 = collection1.mean();
  let meanImage2 = collection2.mean();

  // 3. Processing & Calculation - Period 1
  let regionStats1 = await meanImage1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: taiwan,
    scale: REDUCER_SCALE,
    maxPixels: 1e9,
    crs: 'EPSG:4326' // Specify CRS to avoid issues if default is problematic
  }).getInfo();

  let meanNO2_1 = regionStats1 ? regionStats1[NO2_BAND + '_mean'] : null;
  let countPixels1 = regionStats1 ? regionStats1[NO2_BAND + '_count'] : 0;

  if (countPixels1 === 0) {
    console.log("No valid pixels for Period 1 after quality filtering.");
    console.log("C2");
    return;
  }

  // 3. Processing & Calculation - Period 2
  let regionStats2 = await meanImage2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: taiwan,
    scale: REDUCER_SCALE,
    maxPixels: 1e9,
    crs: 'EPSG:4326'
  }).getInfo();

  let meanNO2_2 = regionStats2 ? regionStats2[NO2_BAND + '_mean'] : null;
  let countPixels2 = regionStats2 ? regionStats2[NO2_BAND + '_count'] : 0;

  if (countPixels2 === 0) {
    console.log("No valid pixels for Period 2 after quality filtering.");
    console.log("C2");
    return;
  }

  // 4. Validation & Final Answer
  if (meanNO2_1 === null || isNaN(meanNO2_1) || meanNO2_2 === null || isNaN(meanNO2_2)) {
    console.log("Calculation resulted in null/NaN values.");
    console.log("C3");
    return;
  }

  console.log(`Period 1 Mean NO2: ${meanNO2_1.toFixed(9)} mol/m^2 (Valid Pixels: ${countPixels1})`);
  console.log(`Period 2 Mean NO2: ${meanNO2_2.toFixed(9)} mol/m^2 (Valid Pixels: ${countPixels2})`);

  if (meanNO2_2 > meanNO2_1) {
    console.log("A"); // Yes, NO2 levels increased
  } else {
    console.log("B"); // No, NO2 levels did not increase
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
